class Solution:
    def stringSequence(self, target: str) -> list[str]:
        ans = []
        curr = ""
        for ch in target:
            # Button 1 appends 'a'
            curr += 'a'
            ans.append(curr)
            # Button 2 cycles up to ch
            for code in range(ord('b'), ord(ch) + 1):
                curr = curr[:-1] + chr(code)
                ans.append(curr)
        return ans

#include <string>
#include <vector>

class Solution {
public:
    std::vector<std::string> stringSequence(std::string target) {
        std::vector<std::string> ans;
        std::string curr = "";
        for (char ch : target) {
            curr += 'a';
            ans.push_back(curr);
            for (char c = 'b'; c <= ch; ++c) {
                curr.back() = c;
                ans.push_back(curr);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public List<String> stringSequence(String target) {
        List<String> ans = new ArrayList<>();
        StringBuilder curr = new StringBuilder();

        for (int i = 0; i < target.length(); i++) {
            char ch = target.charAt(i);
            curr.append('a');
            ans.add(curr.toString());
            for (char c = 'b'; c <= ch; c++) {
                curr.setCharAt(curr.length() - 1, c);
                ans.add(curr.toString());
            }
        }
        return ans;
    }
}

var stringSequence = function(target) {
    const ans = [];
    let curr = "";
    for (let i = 0; i < target.length; i++) {
        const ch = target[i];
        curr += 'a';
        ans.push(curr);
        for (let code = 98; code <= ch.charCodeAt(0); code++) {
            curr = curr.slice(0, -1) + String.fromCharCode(code);
            ans.push(curr);
        }
    }
    return ans;
};
